class AppErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={failed:false};}
  static getDerivedStateFromError(){return {failed:true};}
  componentDidCatch(error,info){console.error("TripMate screen error",error,info);}
  render(){if(!this.state.failed)return this.props.children;return <ThemeProvider theme={theme}><Box className="auth-shell"><Card className="auth-card"><CardContent><Stack spacing={2} textAlign="center"><Avatar className="auth-logo"><TravelExploreRounded/></Avatar><Typography variant="h4">หน้านี้สะดุดนิดหน่อย</Typography><Typography color="text.secondary">ข้อมูลของคุณยังอยู่ ลองเปิดหน้านี้ใหม่อีกครั้ง</Typography><Button variant="contained" onClick={()=>window.location.reload()}>โหลดใหม่</Button><Button href={window.location.pathname}>กลับหน้าหลัก</Button></Stack></CardContent></Card></Box></ThemeProvider>;}
}
const memberColors=["#65BCE8","#E7B94F","#74C7A8","#A895DD","#ED91A5","#7EA9E1","#E69A6D","#64BEB9"];
function memberInitial(member){const name=String(member?.name||"").trim();return Array.from(name)[0]?.toLocaleUpperCase("th-TH")||"?";}
function memberColor(member){const key=String(member?.id||member?.name||"");let hash=0;for(const char of key)hash=(hash*31+char.codePointAt(0))>>>0;return memberColors[hash%memberColors.length];}

function useStoredState(key, initial) {
  const [state, setState] = useState(() => {
    try { const saved = localStorage.getItem(key); return saved ? JSON.parse(saved) : initial; } catch { return initial; }
  });
  useEffect(() => { try { localStorage.setItem(key, JSON.stringify(state)); } catch {} }, [key, state]);
  return [state, setState];
}

